/* ---------------------------------------------------------
   GALLERY (shared by Gallery + Selected pages)
--------------------------------------------------------- */
function sortMixed(values) {
  // numeric years first (ascending), then descriptive text years alphabetically
  const nums = [];
  const words = [];
  values.forEach((v) => {
    if (/^\d+$/.test(v)) nums.push(v);
    else words.push(v);
  });
  nums.sort((a, b) => Number(a) - Number(b));
  words.sort((a, b) => a.localeCompare(b, "he"));
  return [...nums, ...words];
}

function Gallery({ artworks, title, intro }) {
  const [subject, setSubject] = useState("הכל");
  const [technique, setTechnique] = useState("הכל");
  const [year, setYear] = useState("הכל");
  const [sizeCat, setSizeCat] = useState("הכל");
  const [sizeDesc, setSizeDesc] = useState("הכל");
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(null);

  const subjects = useMemo(() => ["הכל", ...Array.from(new Set(artworks.map((a) => a.subject))).sort((a, b) => a.localeCompare(b, "he"))], [artworks]);
  const techniques = useMemo(() => ["הכל", ...Array.from(new Set(artworks.map((a) => a.technique))).sort((a, b) => a.localeCompare(b, "he"))], [artworks]);
  const years = useMemo(() => ["הכל", ...sortMixed(Array.from(new Set(artworks.map((a) => a.year).filter(Boolean))))], [artworks]);
  const sizeCats = useMemo(() => {
    const order = ["קטן מאוד", "קטן", "בינוני", "גדול", "גדול מאוד", "ענק"];
    const present = Array.from(new Set(artworks.map((a) => a.sizeCat).filter(Boolean)));
    present.sort((a, b) => order.indexOf(a) - order.indexOf(b));
    return ["הכל", ...present];
  }, [artworks]);
  const sizeDescs = useMemo(() => ["הכל", ...Array.from(new Set(artworks.map((a) => a.sizeDesc))).sort((a, b) => a.localeCompare(b, "he"))], [artworks]);

  const filtered = useMemo(() => {
    return artworks.filter((a) => {
      if (subject !== "הכל" && a.subject !== subject) return false;
      if (technique !== "הכל" && a.technique !== technique) return false;
      if (year !== "הכל" && a.year !== year) return false;
      if (sizeCat !== "הכל" && a.sizeCat !== sizeCat) return false;
      if (sizeDesc !== "הכל" && a.sizeDesc !== sizeDesc) return false;
      if (query && !a.title.includes(query)) return false;
      return true;
    });
  }, [artworks, subject, technique, year, sizeCat, sizeDesc, query]);

  const hasActiveFilters = subject !== "הכל" || technique !== "הכל" || year !== "הכל" || sizeCat !== "הכל" || sizeDesc !== "הכל" || query !== "";
  const clearAll = () => {
    setSubject("הכל"); setTechnique("הכל"); setYear("הכל"); setSizeCat("הכל"); setSizeDesc("הכל"); setQuery("");
  };

  const selectStyle = {
    fontFamily: "'Assistant', sans-serif",
    fontSize: 13,
    padding: "9px 10px",
    background: "#F7F3EA",
    border: "1px solid #C9BFA9",
    color: "#221D17",
    borderRadius: 2,
    width: "100%",
  };
  const labelStyle = {
    fontFamily: "'Assistant', sans-serif",
    fontSize: 11,
    color: "#8A7E6C",
    marginBottom: 4,
    display: "block",
  };

  const filterFields = [
    ["נושא", subject, setSubject, subjects],
    ["טכניקה", technique, setTechnique, techniques],
    ["שנה", year, setYear, years],
    ["גודל — קטגוריה", sizeCat, setSizeCat, sizeCats],
    ["גודל — תיאור", sizeDesc, setSizeDesc, sizeDescs],
  ];

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "48px 24px 100px" }}>
      <h2 style={{ fontFamily: "'Frank Ruhl Libre', serif", fontSize: 32, fontWeight: 700, color: "#221D17", margin: "0 0 8px" }}>{title}</h2>
      {intro && <p style={{ fontFamily: "'Assistant', sans-serif", fontSize: 15, color: "#5F5449", maxWidth: 600, marginBottom: 26 }}>{intro}</p>}

      <div style={{ padding: "18px 0", borderTop: "1px solid #C9BFA9", borderBottom: "1px solid #C9BFA9", marginBottom: 32 }}>
        <div style={{ marginBottom: 14 }}>
          <label style={labelStyle}>חיפוש לפי כותרת</label>
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="הקלידו מילה מתוך הכותרת..."
            style={{ ...selectStyle, maxWidth: 280 }}
          />
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 14 }}>
          {filterFields.map(([label, val, setter, options]) => (
            <div key={label}>
              <label style={labelStyle}>{label}</label>
              <select value={val} onChange={(e) => setter(e.target.value)} style={selectStyle}>
                {options.map((o) => <option key={o} value={o}>{o}</option>)}
              </select>
            </div>
          ))}
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 14 }}>
          <div style={{ fontFamily: "'Roboto Mono', monospace", fontSize: 11, color: "#A66B33" }}>
            {filtered.length} / {artworks.length}
          </div>
          {hasActiveFilters && (
            <button
              onClick={clearAll}
              style={{ background: "none", border: "none", cursor: "pointer", fontFamily: "'Assistant', sans-serif", fontSize: 12, color: "#8B4A3D", textDecoration: "underline" }}
            >
              נקה סינון
            </button>
          )}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: "40px 28px" }}>
        {filtered.map((art) => (
          <Placard key={art.id} art={art} onClick={() => setActive(art)} />
        ))}
      </div>
      {filtered.length === 0 && (
        <div style={{ fontFamily: "'Assistant', sans-serif", color: "#6B5B4F", padding: "40px 0" }}>לא נמצאו יצירות התואמות את הסינון.</div>
      )}
      <Lightbox art={active} onClose={() => setActive(null)} />
    </div>
  );
}

/* ---------------------------------------------------------
   CONTACT
--------------------------------------------------------- */
function Contact() {
  const [sent, setSent] = useState(false);
  const [sending, setSending] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSending(true);
    const form = e.target;
    try {
      const res = await fetch(form.action, {
        method: "POST",
        body: new FormData(form),
        headers: { Accept: "application/json" },
      });
      if (res.ok) {
        setSent(true);
        form.reset();
      }
    } catch (err) {
      // fall through — user can retry
    }
    setSending(false);
  };

  return (
    <div style={{ maxWidth: 1000, margin: "0 auto", padding: "48px 24px 100px" }}>
      <h2 style={{ fontFamily: "'Frank Ruhl Libre', serif", fontSize: 32, fontWeight: 700, color: "#221D17", marginBottom: 8 }}>צרו קשר</h2>
      <p style={{ fontFamily: "'Assistant', sans-serif", fontSize: 15, color: "#5F5449", maxWidth: 520, marginBottom: 40 }}>
        לפניות בנוגע לאוסף, לתערוכות או לשימוש ביצירות.
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "0.9fr 1.1fr", gap: 56 }} className="contact-grid">
        <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
          <div style={{ fontFamily: "'Assistant', sans-serif", fontSize: 14, color: "#221D17" }}>דבורה זילבר</div>
          <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
            <Phone size={16} color="#A66B33" />
            <span style={{ fontFamily: "'Roboto Mono', monospace", fontSize: 14, color: "#221D17", direction: "ltr" }}>054-563-6612</span>
          </div>
        </div>
        {sent ? (
          <div style={{ fontFamily: "'Assistant', sans-serif", fontSize: 15, color: "#3E4A3B", padding: "20px 0" }}>
            ההודעה נשלחה בהצלחה. תודה שפניתם!
          </div>
        ) : (
          <form
            action="https://formsubmit.co/silberdeb@gmail.com"
            method="POST"
            onSubmit={handleSubmit}
            style={{ display: "flex", flexDirection: "column", gap: 14 }}
          >
            <input type="hidden" name="_subject" value="פנייה חדשה מאתר אריה ברמץ" />
            <input type="hidden" name="_captcha" value="false" />
            <input
              name="name"
              required
              placeholder="שם"
              style={{ fontFamily: "'Assistant', sans-serif", fontSize: 14, padding: "12px 14px", background: "#F7F3EA", border: "1px solid #C9BFA9", borderRadius: 2, color: "#221D17" }}
            />
            <input
              name="email"
              type="email"
              required
              placeholder="אימייל"
              style={{ fontFamily: "'Assistant', sans-serif", fontSize: 14, padding: "12px 14px", background: "#F7F3EA", border: "1px solid #C9BFA9", borderRadius: 2, color: "#221D17" }}
            />
            <textarea
              name="message"
              required
              placeholder="הודעה"
              rows={5}
              style={{ fontFamily: "'Assistant', sans-serif", fontSize: 14, padding: "12px 14px", background: "#F7F3EA", border: "1px solid #C9BFA9", borderRadius: 2, color: "#221D17", resize: "vertical" }}
            />
            <button type="submit" disabled={sending} style={{ ...btnPrimary, alignSelf: "flex-start", opacity: sending ? 0.6 : 1 }}>
              {sending ? "שולח..." : "שליחה"}
            </button>
          </form>
        )}
      </div>
      <style>{`@media (max-width: 700px) { .contact-grid { grid-template-columns: 1fr !important; } }`}</style>
    </div>
  );
}

/* ---------------------------------------------------------
   APP
--------------------------------------------------------- */
export default function App() {
  const [page, setPage] = useState("home");
  const selectedWorks = useMemo(
    () => ARTWORKS.filter((a) => a.index % SELECTED_EVERY_N === 0),
    []
  );

  return (
    <div dir="rtl" style={{ background: "#EFE9DD", minHeight: "100vh" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Frank+Ruhl+Libre:wght@500;700&family=Assistant:wght@400;600;700&family=Roboto+Mono:wght@400;500&display=swap');
        * { box-sizing: border-box; }
        input::placeholder, textarea::placeholder { color: #A79A85; }
        body { direction: rtl; }
      `}</style>
      <Nav page={page} setPage={setPage} />
      {page === "home" && <Home setPage={setPage} />}
      {page === "gallery" && (
        <Gallery
          artworks={ARTWORKS}
          title="גלריה מלאה"
          intro={`${ARTWORKS.length} יצירות קטלוגיות, ניתנות לסינון לפי נושא ותקופה.`}
        />
      )}
      {page === "selected" && (
        <Gallery artworks={selectedWorks} title="יצירות נבחרות" intro="מבחר ראשוני שנפרש על פני הארכיון — יעודכן בהמשך לפי בחירה אישית." />
      )}
      {page === "contact" && <Contact />}
      <div
        style={{
          borderTop: "1px solid #C9BFA9",
          padding: "24px",
          textAlign: "center",
          fontFamily: "'Assistant', sans-serif",
          fontSize: 12,
          color: "#8A7E6C",
        }}
      >
        אריה ברמץ — שמן על בד (C) כל הזכויות שמורות למשפחה
      </div>
    </div>
  );
}
